{
  "items": [
    {
      "name": "iteratedDeriv_zero",
      "module_name": "Mathlib.Analysis.Calculus.IteratedDeriv.Defs",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {F : Type u_2} [inst_1 : NormedAddCommGroup F]\n  [inst_2 : NormedSpace 𝕜 F] {f : 𝕜 → F}, iteratedDeriv 0 f = f"
    },
    {
      "name": "LaurentSeries.hasseDeriv_zero",
      "module_name": "Mathlib.RingTheory.LaurentSeries",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {V : Type u_2} [inst_1 : AddCommGroup V] [inst_2 : Module R V],\n  LaurentSeries.hasseDeriv R 0 = LinearMap.id"
    },
    {
      "name": "iteratedDeriv_fun_id",
      "module_name": "Mathlib.Analysis.Calculus.IteratedDeriv.Lemmas",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {n : ℕ} {x : 𝕜},\n  iteratedDeriv n (fun a => a) x = if n = 0 then x else if n = 1 then 1 else 0"
    },
    {
      "name": "Polynomial.hasseDeriv_zero",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R], Polynomial.hasseDeriv 0 = LinearMap.id"
    },
    {
      "name": "iteratedDerivWithin_zero",
      "module_name": "Mathlib.Analysis.Calculus.IteratedDeriv.Defs",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {F : Type u_2} [inst_1 : NormedAddCommGroup F]\n  [inst_2 : NormedSpace 𝕜 F] {f : 𝕜 → F} {s : Set 𝕜}, iteratedDerivWithin 0 f s = f"
    }
  ]
}
